SELECT p.gender, p.age, d.icd_code, s.stay_id, s.hadm_id, s.intime, s.outtime, s.los, row_number() OVER(PARTITION BY p.gender, p.age, d.icd_code ORDER BY s.hadm_id) AS stay_rank, dense_rank() OVER(PARTITION BY p.gender, p.age, d.icd_code ORDER BY s.hadm_id) AS admission_rank, COUNT(*) OVER(PARTITION BY p.gender, p.age, d.icd_code) AS total_stays, SUM(CASE WHEN s.outtime - s.intime <= 30 THEN 1 ELSE 0 END) OVER(PARTITION BY p.gender, p.age, d.icd_code) AS early_departures, SUM(CASE WHEN d.major_diagnostic_category = 'Major Complication' THEN 1 ELSE 0 END) OVER(PARTITION BY p.gender, p.age, d.icd_code) AS major_complications, percent_rank() OVER(PARTITION BY p.gender, p.age, d.icd_code ORDER BY s.hadm_id) AS percentile_rank FROM patients p JOIN admissions a ON a.subject_id = p.subject_id JOIN stay s ON s.subject_id = p.subject_id AND s.hadm_id = a.hadm_id JOIN diagnoses_icd d ON d.subject_id = p.subject_id AND d.hadm_id = a.hadm_id WHERE p.gender = 'Female' AND p.age BETWEEN 69 AND 79 AND d.icd_code = '440.0' GROUP BY p.gender, p.age, d.icd_code, s.stay_id, s.hadm_id, s.intime, s.outtime, s.los ORDER BY p.gender, p.age, d.icd_code, stay_rank NULLS LAST;